  5	package com.agentclientprotocol.sdk.spec;
  6	
  7	import com.agentclientprotocol.sdk.json.TypeRef;
  8	import org.jspecify.annotations.Nullable;
  9	import reactor.core.publisher.Mono;
 10	
 11	/**
 12	 * Represents an Agent Client Protocol (ACP) session that handles communication between
 13	 * clients and agents. This interface provides methods for sending requests and
 14	 * notifications, as well as managing the session lifecycle.
 15	 *
 16	 * <p>
 17	 * The session operates asynchronously using Project Reactor's {@link Mono} type for
 18	 * non-blocking operations. It supports both request-response patterns and one-way
 19	 * notifications.
 20	 * </p>
 21	 *
 22	 * <p>
 23	 * ACP is bidirectional - both clients and agents can send requests to each other:
 24	 * </p>
 25	 * <ul>
 26	 * <li>Client → Agent: initialize, newSession, prompt, setSessionMode, etc.</li>
 27	 * <li>Agent → Client: readTextFile, writeTextFile, requestPermission, sessionUpdate,
 28	 * etc.</li>
 29	 * </ul>
 30	 *
 31	 * @author Mark Pollack
 32	 * @author Christian Tzolov
 33	 */
 34	public interface AcpSession {
 35	
 36		/**
 37		 * Sends a request to the peer and expects a response of type T.
 38		 *
 39		 * <p>
 40		 * This method handles the request-response pattern where a response is expected from
 41		 * the peer (agent or client). The response type is determined by the provided
 42		 * TypeReference.
 43		 * </p>
 44		 * @param <T> the type of the expected response
 45		 * @param method the name of the method to be called on the peer
 46		 * @param requestParams the parameters to be sent with the request
 47		 * @param typeRef the TypeReference describing the expected response type
 48		 * @return a Mono that will emit the response when received. A response without a
 49		 * result ({@code "result": null}) reads as {@code {}} for an
 50		 * {@link AcpSchema.DefaultOnNull} type, completes the Mono empty for an extension
 51		 * ({@code _}-prefixed) method, and fails the Mono otherwise.
 52		 */
 53		<T> Mono<T> sendRequest(String method, Object requestParams, TypeRef<T> typeRef);
 54	
 55		/**
 56		 * Sends a notification to the peer without parameters.
 57		 *
 58		 * <p>
 59		 * This method implements the notification pattern where no response is expected from
 60		 * the peer. It's useful for fire-and-forget scenarios like session updates.
 61		 * </p>
 62		 * @param method the name of the notification method to be called on the peer
 63		 * @return a Mono that completes when the notification has been sent
 64		 */
 65		default Mono<Void> sendNotification(String method) {
 66			return sendNotification(method, null);
 67		}
 68	
 69		/**
 70		 * Sends a notification to the peer with parameters.
 71		 *
 72		 * <p>
 73		 * Similar to {@link #sendNotification(String)} but allows sending additional
 74		 * parameters with the notification.
 75		 * </p>
 76		 * @param method the name of the notification method to be sent to the peer
 77		 * @param params parameters to be sent with the notification
 78		 * @return a Mono that completes when the notification has been sent
 79		 */
 80		Mono<Void> sendNotification(String method, @Nullable Object params);
 81	
 82		/**
 83		 * Closes the session and releases any associated resources asynchronously.
 84		 * @return a {@link Mono<Void>} that completes when the session has been closed.
 85		 */
 86		Mono<Void> closeGracefully();
 87	
 88		/**
 89		 * Closes the session and releases any associated resources.
 90		 */
 91		void close();
 92	
 93	}
