 98	package com.agentclientprotocol.sdk.spec;
 99	
100	import java.util.Map;
101	import java.util.function.BiFunction;
102	import java.util.concurrent.CancellationException;
103	
104	import com.agentclientprotocol.sdk.error.AcpErrorCodes;
105	import com.agentclientprotocol.sdk.error.AcpProtocolException;
106	import com.agentclientprotocol.sdk.util.HandlerFailures;
107	import org.jspecify.annotations.Nullable;
108	import org.slf4j.Logger;
109	import org.slf4j.LoggerFactory;
110	import reactor.core.Exceptions;
111	import reactor.core.publisher.Mono;
112	
113	/**
114	 * How a session answers the requests and notifications its peer sends, the same way for
115	 * both session sides.
116	 */
117	final class InboundMessages {
118	
119		private static final Logger LOGGER = LoggerFactory.getLogger(InboundMessages.class);
120	
121		/** The message of the internal error a handler's unexpected exception is answered with. */
122		static final String INTERNAL_ERROR_MESSAGE = "Internal error";
123	
124		private InboundMessages() {
125		}
126	
127		/**
128		 * The params a handler receives. JSON-RPC lets a request or notification omit them;
129		 * an omitted params reads as an empty object, which is what a peer sending {@code {}}
130		 * would deliver, so handlers never see null.
131		 */
132		static Object paramsOrEmpty(@Nullable Object params) {
133			return (params != null) ? params : Map.of();
134		}
135	
136		/**
137		 * Passes a notification to the handler registered for its method; a handler that fails
138		 * (params it cannot read, say) is logged and skipped. One without a handler is ignored,
139		 * logged by its method only: its params can carry personal data (agents send
140		 * {@code _auth/status_update}, whose params carry the account's email address). An
141		 * extension notification ({@code _}-prefixed) is logged at DEBUG, since ACP asks
142		 * implementations to ignore notifications they do not recognize and a peer may send many;
143		 * a protocol notification without a handler is logged at WARN, as it usually means a
144		 * handler was not registered.
145		 */
146		static <H> Mono<Void> deliver(Logger logger, AcpSchema.JSONRPCNotification notification,
147				Map<String, H> handlers, BiFunction<H, Object, Mono<Void>> handle) {
148			H handler = handlers.get(notification.method());
149			if (handler == null) {
150				if (ExtensionMethods.isExtension(notification.method())) {
151					logger.debug("No handler registered for extension notification method: {}", notification.method());
152				}
153				else {
154					logger.warn("No handler registered for notification method: {}", notification.method());
155				}
156				return Mono.empty();
157			}
158			// A notification has no answer to carry a failure: it is logged (method and error
159			// only) and the session reads on. A failure must not end the inbound stream. An Error
160			// (HandlerFailures) is logged at ERROR with its stack trace.
161			return HandlerFailures.invoke(() -> handle.apply(handler, paramsOrEmpty(notification.params())))
162				.onErrorResume(error -> {
163					Throwable failure = HandlerFailures.contain(error);
164					if (failure instanceof HandlerFailures.HandlerError) {
165						LOGGER.error("Notification {} handler failed with an error and was skipped",
166								notification.method(), failure.getCause());
167					}
168					else if (error instanceof AcpError peerError) {
169						// The peer's answer to a call the handler made: its message and data are the
170						// peer's text, logged at DEBUG only.
171						logger.warn("Notification {} failed and was skipped: the peer answered {} {}",
172								notification.method(), peerError.getCode(), AcpErrorCodes.getDescription(peerError.getCode()));
173						logger.debug("Notification {} failed: {}", notification.method(), peerError.toString());
174					}
175					else {
176						logger.warn("Notification {} failed and was skipped: {}", notification.method(), error.toString());
177					}
178					return Mono.empty();
179				});
180		}
181	
182		/** A request always gets a response: a handler that completes empty is answered with an error. */
183		static <T> Mono<T> requireResult(Mono<T> result, String method) {
184			return result.switchIfEmpty(Mono.error(() -> new AcpProtocolException(AcpErrorCodes.INTERNAL_ERROR,
185					"The " + method + " handler produced no response")));
186		}
187	
188		static AcpSchema.JSONRPCResponse result(AcpSchema.JSONRPCRequest request, Object result) {
189			return new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, request.id(), result, null);
190		}
191	
192		static AcpSchema.JSONRPCResponse error(AcpSchema.JSONRPCRequest request, int code, String message,
193				@Nullable Object data) {
194			return new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, request.id(), null,
195					new AcpSchema.JSONRPCError(code, message, data));
196		}
197	
198		/**
199		 * The response to a request whose handling failed: an {@link AcpProtocolException} keeps
200		 * its code, message and data (it is the handler's intended answer), an {@link AcpError}
201		 * that escaped the handler passes on the error it carries unchanged, a cancellation
202		 * ({@link #isCancellation}) is the handler cancelling its own work (ACP v1 internal
203		 * cancellation: the same {@code -32800} as a cancel from the caller), anything else is an
204		 * internal error with the generic message {@value #INTERNAL_ERROR_MESSAGE}: an exception's
205		 * message can carry paths, queries or credentials the peer must not see, so it is logged
206		 * here, at WARN with its stack trace, and not sent. A handler that failed with an
207		 * {@link Error} ({@link HandlerFailures}) is answered with an internal error that names
208		 * the method and the error's type only, and the error is logged at ERROR with its stack
209		 * trace.
210		 */
211		static AcpSchema.JSONRPCResponse error(AcpSchema.JSONRPCRequest request, Throwable error) {
212			if (HandlerFailures.contain(error) instanceof HandlerFailures.HandlerError handlerError) {
213				Throwable cause = (handlerError.getCause() != null) ? handlerError.getCause() : handlerError;
214				LOGGER.error("The {} handler failed with {}; answered {} (Internal error)", request.method(),
215						cause.getClass().getName(), AcpErrorCodes.INTERNAL_ERROR, cause);
216				return error(request, AcpErrorCodes.INTERNAL_ERROR,
217						"Internal error in the " + request.method() + " handler (" + cause.getClass().getName() + ")",
218						null);
219			}
220			if (error instanceof AcpProtocolException protocolException) {
221				return new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, request.id(), null,
222						AcpSchema.JSONRPCError.from(protocolException));
223			}
224			if (error instanceof AcpError peerError) {
225				// A request the handler made failed and the handler let it escape: the peer's
226				// error is passed on as it is, code, message and data.
227				LOGGER.debug("The {} handler let a peer error escape; passed on {}", request.method(), peerError.getCode());
228				return new AcpSchema.JSONRPCResponse(AcpSchema.JSONRPC_VERSION, request.id(), null, peerError.getError());
229			}
230			if (isCancellation(error)) {
231				String message = error.getMessage();
232				return error(request, AcpErrorCodes.REQUEST_CANCELLED,
233						(message != null) ? message : InboundRequests.CANCELLED_MESSAGE, null);
234			}
235			LOGGER.warn("The {} handler failed; answered {} ({})", request.method(), AcpErrorCodes.INTERNAL_ERROR,
236					INTERNAL_ERROR_MESSAGE, error);
237			return error(request, AcpErrorCodes.INTERNAL_ERROR, INTERNAL_ERROR_MESSAGE, null);
238		}
239	
240		/**
241		 * Whether a handler's failure means its work was cancelled: a
242		 * {@link CancellationException} or an interrupt (Reactor's {@code block()} wraps it), or
243		 * an {@link AcpProtocolException} with code -32800.
244		 */
245		static boolean isCancellation(Throwable error) {
246			Throwable unwrapped = Exceptions.unwrap(error);
247			return unwrapped instanceof CancellationException || unwrapped instanceof InterruptedException
248					|| (error instanceof AcpProtocolException protocolException
249							&& protocolException.getCode() == AcpErrorCodes.REQUEST_CANCELLED);
250		}
251	
252	}
