257	package com.agentclientprotocol.sdk.spec;
258	
259	import java.math.BigInteger;
260	import java.util.Map;
261	import java.util.concurrent.ConcurrentHashMap;
262	import java.util.function.Function;
263	import java.util.function.Supplier;
264	
265	import com.agentclientprotocol.sdk.error.AcpErrorCodes;
266	import org.jspecify.annotations.Nullable;
267	import org.slf4j.Logger;
268	import org.slf4j.LoggerFactory;
269	import reactor.core.publisher.Mono;
270	import reactor.core.publisher.Sinks;
271	
272	/**
273	 * The requests a session received from its peer and has not answered yet, keyed by request
274	 * id, so that a {@code $/cancel_request} can cancel one (ACP v1, Cancellation), the same way
275	 * for both session sides.
276	 *
277	 * <p>
278	 * A cancelled request still gets exactly one response: the handler's, when it came first,
279	 * otherwise the error {@code -32800} (Request cancelled). Both race inside one {@code Mono}
280	 * ({@link Mono#takeUntilOther}), which signals at most once, so there is never a second
281	 * response for the id. The handler's subscription is cancelled, which also cancels the
282	 * requests it was waiting on (their sessions send {@code $/cancel_request} in turn).
283	 * </p>
284	 */
285	final class InboundRequests {
286	
287		private static final Logger logger = LoggerFactory.getLogger(InboundRequests.class);
288	
289		static final String CANCELLED_MESSAGE = "Request cancelled";
290	
291		/** The cancel trigger of each request being handled, keyed by its normalised id. */
292		private final ConcurrentHashMap<Object, Cancel> inFlight = new ConcurrentHashMap<>();
293	
294		/** One request's cancel: the trigger, and whether a cancel has been asked for. */
295		private static final class Cancel {
296	
297			final Sinks.Empty<Void> trigger = Sinks.empty();
298	
299			final AcpSchema.JSONRPCRequest request;
300	
301			/** The answer to send in place of the cancelled handler's, or null for the default. */
302			volatile @Nullable Supplier<AcpSchema.JSONRPCResponse> answer;
303	
304			volatile boolean requested;
305	
306			Cancel(AcpSchema.JSONRPCRequest request) {
307				this.request = request;
308			}
309	
310			boolean fire() {
311				this.requested = true;
312				return this.trigger.tryEmitEmpty().isSuccess();
313			}
314	
315		}
316	
317		/** Set once the session closes: requests still arriving are cancelled at once. */
318		private volatile boolean closed;
319	
320		/**
321		 * Makes {@code response}, the answer to {@code request}, cancellable by
322		 * {@link #cancel}, which answers {@code -32800}. See
323		 * {@link #track(AcpSchema.JSONRPCRequest, Mono, Supplier)}.
324		 */
325		Mono<AcpSchema.JSONRPCResponse> track(AcpSchema.JSONRPCRequest request, Mono<AcpSchema.JSONRPCResponse> response) {
326			return track(request, response, () -> cancelled(request));
327		}
328	
329		/**
330		 * Makes {@code response}, the answer to {@code request}, cancellable by
331		 * {@link #cancel}. Call it on the complete answer: whatever {@code response} emits is the
332		 * request's only response, and when a cancel wins the race, {@code whenCancelled}
333		 * supplies the response instead. A request without an id cannot be cancelled and is
334		 * passed through.
335		 *
336		 * <p>
337		 * The request becomes cancellable only once {@code response} is subscribed, so a cancel
338		 * always cancels a running handler (whose own cancellation, a prompt's turn included,
339		 * runs before the answer is produced), and stops being cancellable as soon as its
340		 * response is produced.
341		 * </p>
342		 */
343		Mono<AcpSchema.JSONRPCResponse> track(AcpSchema.JSONRPCRequest request, Mono<AcpSchema.JSONRPCResponse> response,
344				Supplier<AcpSchema.JSONRPCResponse> whenCancelled) {
345			Object key = key(request.id());
346			if (key == null) {
347				return response;
348			}
349			return Mono.defer(() -> {
350				Cancel cancel = new Cancel(request);
351				// takeUntilOther subscribes the trigger before the response, and passes
352				// onSubscribe down only once the response is subscribed: registering here means
353				// a cancel can only reach a handler that is running. A handler that fails once
354				// it is cancelled (an interrupted blocking handler throws) was cancelled too.
355				return response.onErrorResume(error -> cancel.requested, error -> Mono.empty())
356					.takeUntilOther(cancel.trigger.asMono())
357					.doOnSubscribe(subscription -> register(key, cancel, request))
358					.switchIfEmpty(Mono.fromSupplier(() -> {
359						Supplier<AcpSchema.JSONRPCResponse> chosen = cancel.answer;
360						return (chosen != null) ? chosen.get() : whenCancelled.get();
361					}))
362					.doOnNext(answer -> this.inFlight.remove(key, cancel))
363					.doFinally(signal -> this.inFlight.remove(key, cancel));
364			});
365		}
366	
367		private void register(Object key, Cancel cancel, AcpSchema.JSONRPCRequest request) {
368			if (this.closed) {
369				cancel.fire();
370				return;
371			}
372			if (this.inFlight.putIfAbsent(key, cancel) != null) {
373				// The peer reused the id of a request still being handled: a cancel names the
374				// first one.
375				logger.warn("Request id {} is already in use by an unanswered request", request.id());
376			}
377			else if (this.closed) {
378				// Closed while registering: cancelAll may not have seen this request.
379				cancel.fire();
380			}
381		}
382	
383		/**
384		 * Cancels the request with this id, if it is still being handled.
385		 * @return whether a request was cancelled; false when the id is unknown or already
386		 * answered
387		 */
388		boolean cancel(@Nullable Object requestId) {
389			Object key = key(requestId);
390			Cancel cancel = (key != null) ? this.inFlight.get(key) : null;
391			if (cancel == null || !cancel.fire()) {
392				logger.debug("Ignored $/cancel_request for id {}: no request with that id is being handled", requestId);
393				return false;
394			}
395			logger.debug("Cancelled request {}", requestId);
396			return true;
397		}
398	
399		/**
400		 * Answers every request of one method still being handled for a session with the given
401		 * response instead of its handler's, and stops the handler: the client's own obligation when
402		 * it cancels a prompt turn (ACP v1, prompt turn, Cancellation: pending
403		 * {@code session/request_permission} requests are answered {@code cancelled}).
404		 * @param method the request method
405		 * @param sessionId the session the requests belong to
406		 * @param answer the response to send for each such request
407		 * @return how many requests were answered
408		 */
409		int answer(String method, String sessionId,
410				Function<AcpSchema.JSONRPCRequest, AcpSchema.JSONRPCResponse> answer) {
411			int answered = 0;
412			for (Cancel cancel : this.inFlight.values()) {
413				AcpSchema.JSONRPCRequest request = cancel.request;
414				if (method.equals(request.method()) && sessionId.equals(sessionIdOf(request.params()))) {
415					cancel.answer = () -> answer.apply(request);
416					if (cancel.fire()) {
417						answered++;
418						logger.debug("Answered pending {} request {} for cancelled session {}", method, request.id(),
419								sessionId);
420					}
421				}
422			}
423			return answered;
424		}
425	
426		private static @Nullable Object sessionIdOf(@Nullable Object params) {
427			if (params instanceof AcpSchema.RequestPermissionRequest request) {
428				return request.sessionId();
429			}
430			if (params instanceof Map<?, ?> map) {
431				return map.get("sessionId");
432			}
433			return null;
434		}
435	
436		/**
437		 * Cancels every request being handled, and every request that arrives after: the session
438		 * is closing (ACP v1 internal cancellation). Each is answered as if the peer had
439		 * cancelled it, so far as the transport still delivers.
440		 */
441		void cancelAll() {
442			this.closed = true;
443			for (Object key : this.inFlight.keySet()) {
444				cancel(key);
445			}
446		}
447	
448		/**
449		 * Cancels the request a {@code $/cancel_request} notification names. The params are read
450		 * here rather than through {@link AcpTransport#unmarshalParams}: a notification has no
451		 * response to carry a -32602, so params without a usable {@code requestId} (missing, null,
452		 * or not a string or integer, as the schema's {@code RequestId} requires) are logged and
453		 * ignored.
454		 */
455		boolean cancel(AcpSchema.JSONRPCNotification notification) {
456			Object requestId = requestId(notification.params());
457			if (!isRequestId(requestId)) {
458				logger.debug("Ignored $/cancel_request with invalid params {}", notification.params());
459				return false;
460			}
461			return cancel(requestId);
462		}
463	
464		/** The number of requests being handled. */
465		int size() {
466			return this.inFlight.size();
467		}
468	
469		static AcpSchema.JSONRPCResponse cancelled(AcpSchema.JSONRPCRequest request) {
470			return InboundMessages.error(request, AcpErrorCodes.REQUEST_CANCELLED, CANCELLED_MESSAGE, null);
471		}
472	
473		/**
474		 * The id a {@code $/cancel_request} names. Its params arrive as a map from the JSON
475		 * transports and as the typed record from in-process ones.
476		 */
477		private static @Nullable Object requestId(@Nullable Object params) {
478			if (params instanceof AcpSchema.CancelRequestNotification notification) {
479				return notification.requestId();
480			}
481			if (params instanceof Map<?, ?> map) {
482				return map.get("requestId");
483			}
484			return null;
485		}
486	
487		/** A JSON-RPC id the schema allows and a request can carry: a string or an integer. */
488		private static boolean isRequestId(@Nullable Object id) {
489			return id instanceof String || id instanceof Integer || id instanceof Long || id instanceof Short
490					|| id instanceof Byte || (id instanceof BigInteger big && big.bitLength() < Long.SIZE);
491		}
492	
493		/**
494		 * The table key of a JSON-RPC id. An integer id may be read as an Integer in one message
495		 * and a Long in another, so integer types compare by value; a string id never equals a
496		 * number, and a fractional or out-of-range number is kept as it is. A null id cannot be
497		 * correlated.
498		 */
499		static @Nullable Object key(@Nullable Object id) {
500			if (id instanceof Integer || id instanceof Long || id instanceof Short || id instanceof Byte) {
501				return ((Number) id).longValue();
502			}
503			if (id instanceof BigInteger big && big.bitLength() < Long.SIZE) {
504				return big.longValue();
505			}
506			return id;
507		}
508	
509	}

