 28	/**
 29	 * Default implementation of the ACP (Agent Client Protocol) client session that manages
 30	 * bidirectional JSON-RPC communication between clients and agents. This implementation
 31	 * follows the ACP specification for message exchange and transport handling.
 32	 *
 33	 * <p>
 34	 * The session manages:
 35	 * <ul>
 36	 * <li>Request/response handling with unique message IDs</li>
 37	 * <li>Notification processing</li>
 38	 * <li>Message timeout management</li>
 39	 * <li>Transport layer abstraction</li>
 40	 * </ul>
 41	 *
 42	 * <p>
 43	 * This is the client-side session that sends requests to an agent (initialize,
 44	 * newSession, prompt, etc.) and handles incoming requests from the agent (readTextFile,
 45	 * writeTextFile, requestPermission, etc.)
 46	 * </p>
 47	 *
 48	 * @author Mark Pollack
 49	 * @author Christian Tzolov
 50	 */
 51	public class AcpClientSession implements AcpSession {
 52	
 53		private static final Logger logger = LoggerFactory.getLogger(AcpClientSession.class);
 54	
 55		/** Duration to wait for request responses before timing out */
 56		private final Duration requestTimeout;
 57	
 58		/**
 59		 * The JVM-wide daemon timer shared by every session (see AcpSchedulers); never disposed here.
 60		 */
 61		private final Scheduler timeoutScheduler;
 62	
 63		/** Transport layer implementation for message exchange */
 64		private final AcpClientTransport transport;
 65	
 66		/** Requests and notifications sent to the agent, and the requests waiting for a response */
 67		private final OutboundMessages outbound;
 68	
 69		/** Requests from the agent still being handled, which a $/cancel_request can cancel */
 70		private final InboundRequests inbound = new InboundRequests();
 71	
 72		/** Map of request handlers keyed by method name */
 73		private final ConcurrentHashMap<String, RequestHandler<?>> requestHandlers = new ConcurrentHashMap<>();
 74	
 75		/** Map of notification handlers keyed by method name */
 76		private final ConcurrentHashMap<String, NotificationHandler> notificationHandlers = new ConcurrentHashMap<>();
 77	
 78		/**
 79		 * Notifications waiting for in-order delivery, and responses waiting for the notifications
 80		 * before them to be handled; completed when the session closes
 81		 */
 82		private final InboundOrder<AcpSchema.JSONRPCNotification> notifications = new InboundOrder<>();
 83	
 84		/** Subscription draining the notifications in order */
 85		private final Disposable notificationSubscription;
 86	
 87		/** Completes when the notification drain terminates; awaited by {@link #closeGracefully()} */
 88		private final Sinks.Empty<Void> notificationDrainTerminated = Sinks.empty();
