 90		/**
 91		 * Set when the transport's {@code connect()} fails. A transport that refuses to connect
 92		 * (already connected, process failed to start, socket unreachable) can never deliver a
 93		 * response, so every request is failed immediately with the cause instead of waiting
 94		 * out the request timeout.
 95		 */
 96		private volatile @Nullable Throwable connectFailure;
 97	
 98		/** Set once this session starts closing itself, so a transport termination it caused is not reported. */
 99		private volatile boolean closing;
