121		 * Functional interface for handling incoming JSON-RPC notifications. Implementations
122		 * should process the notification parameters without returning a response.
123		 */
124		@FunctionalInterface
125		public interface NotificationHandler {
126	
127			/**
128			 * Handles an incoming notification with the given parameters.
129			 * @param params The notification parameters; an omitted params arrives as an empty
130			 * object
