137		/**
138		 * Creates a new AcpClientSession with the specified configuration and handlers.
139		 * @param requestTimeout Duration to wait for responses
140		 * @param transport Transport implementation for message exchange
141		 * @param requestHandlers Map of method names to request handlers
142		 * @param notificationHandlers Map of method names to notification handlers
143		 * @param connectHook Hook that allows transforming the connection Publisher prior to
144		 * subscribing
145		 */
146		public AcpClientSession(Duration requestTimeout, AcpClientTransport transport,
147				Map<String, RequestHandler<?>> requestHandlers, Map<String, NotificationHandler> notificationHandlers,
148				Function<? super Mono<Void>, ? extends Publisher<Void>> connectHook) {
149	
150			Assert.notNull(requestTimeout, "The requestTimeout can not be null");
151			Assert.notNull(transport, "The transport can not be null");
152			Assert.notNull(requestHandlers, "The requestHandlers can not be null");
153			Assert.notNull(notificationHandlers, "The notificationHandlers can not be null");
154	
155			this.requestTimeout = requestTimeout;
156			this.transport = transport;
157			// A response completes its caller only once the notifications that arrived before it
158			// have been handled: a prompt turn's updates come before its response.
159			this.outbound = new OutboundMessages(transport, requestTimeout, () -> this.connectFailure,
160					AcpClientSession::notConnected, "agent", this.notifications);
161			this.requestHandlers.putAll(requestHandlers);
162			this.notificationHandlers.putAll(notificationHandlers);
163	
164			logger.debug("AcpClientSession created with {} request handlers: {}",
165					requestHandlers.size(), requestHandlers.keySet());
166			logger.debug("AcpClientSession created with {} notification handlers: {}",
167					notificationHandlers.size(), notificationHandlers.keySet());
168	
169			// One shared daemon timer for every session in the JVM (see AcpSchedulers).
170			this.timeoutScheduler = AcpSchedulers.timeouts();
171	
172			// Serialize notification delivery: each notification's Mono completes before the next
173			// one starts, preserving arrival order even when handlers do async work. A response
174			// is released in its place among them (InboundOrder).
175			this.notificationSubscription = this.notifications
176				.drain(notification -> handleIncomingNotification(notification).onErrorComplete(t -> {
177					logger.error("Error handling notification: {}", t.getMessage());
178					return true;
179				}))
180				.doFinally(signal -> {
181					this.notifications.releaseHeld();
182					this.notificationDrainTerminated.tryEmitEmpty();
183				})
184				.subscribe(ignored -> {
185				}, error -> logger.warn("Notification delivery ended with an error", error));
186	
187			this.transport.connect(mono -> mono.doOnNext(this::handle).then(Mono.empty()))
188				.transform(connectHook)
189				.subscribe(v -> {
190				}, this::onConnectFailure);
191	
192			// A transport that refuses synchronously (stdio does, and every transport does when
193			// asked to connect twice) fails construction rather than handing back a session
194			// whose first request would time out.
195			Throwable failure = this.connectFailure;
196			if (failure != null) {
197				this.notifications.complete();
198				this.notificationSubscription.dispose();
199				// A refusal to connect at all (a reused transport) is a misuse, not a lost connection.
200				throw new IllegalStateException("ACP client transport is not connected: " + failure.getMessage(), failure);
201			}
202	
203			// When the transport later terminates (peer gone, stream failed for good), pending
204			// requests fail at once with the cause instead of waiting out the request timeout.
205			this.transport.awaitTermination().subscribe(v -> {
206			}, this::onTransportTerminated, () -> onTransportTerminated(null));
207		}
208	
209		private void onTransportTerminated(@Nullable Throwable cause) {
210			if (this.closing) {
211				return;
212			}
213			Throwable failure = cause != null ? cause : new IllegalStateException("ACP client transport terminated");
214			this.connectFailure = failure;
215			if (cause != null) {
216				logger.warn("ACP client transport terminated: {}", cause.getMessage());
217			}
218			else {
219				logger.debug("ACP client transport terminated by the peer");
220			}
221			dismissPendingResponses(failure);
222		}
223	
224		private void onConnectFailure(Throwable error) {
225			this.connectFailure = error;
226			logger.error("ACP client transport failed to connect; every request on this session will fail: {}",
227					error.getMessage());
228			dismissPendingResponses(error);
229		}
230	
231		private static AcpConnectionException notConnected(Throwable cause) {
232			return new AcpConnectionException("ACP client transport is not connected: " + cause.getMessage(), cause);
233		}
234	
235		private void dismissPendingResponses() {
236			dismissPendingResponses(null);
237		}
238	
239		private void dismissPendingResponses(@Nullable Throwable cause) {
240			this.outbound.dismissPending(cause);
241		}
242	
243		private void handle(AcpSchema.JSONRPCMessage message) {
244			if (message instanceof AcpSchema.JSONRPCResponse response) {
245				this.outbound.complete(response);
246			}
247			else if (message instanceof AcpSchema.JSONRPCRequest request) {
248				respondTo(request);
249			}
250			else if (message instanceof AcpSchema.JSONRPCNotification notification) {
251				if (AcpSchema.METHOD_CANCEL_REQUEST.equals(notification.method())) {
252					// Not queued behind the ordered notification drain: a slow session/update
253					// handler must not delay cancelling a pending request.
254					this.inbound.cancel(notification);
255				}
256				else {
257					enqueue(notification);
258				}
259			}
260			else {
261				logger.warn("Received unknown message type: {}", message.getClass().getName());
262			}
263		}
264	
265		/**
266		 * Answers a request from the agent; a failed handler is answered with an error response,
267		 * a request cancelled by $/cancel_request with -32800 unless it already answered. The
268		 * handler is called only once the notifications that arrived before the request have been
269		 * handled (InboundOrder), so a permission request follows the tool_call update before it;
270		 * the request is tracked from its arrival, so a $/cancel_request reaches it while it waits.
271		 */
272		private void respondTo(AcpSchema.JSONRPCRequest request) {
273			logger.debug("Received request method={} id={}", request.method(), request.id());
274			logger.trace("Incoming request method='{}' id={}", request.method(), request.id());
275			Mono<Void> inOrder = Mono.create(sink -> this.notifications.inOrder(sink::success));
276			this.inbound.track(request, inOrder.then(handleIncomingRequest(request)))
277				.onErrorResume(error -> Mono.just(InboundMessages.error(request, error)))
278				.flatMap(this.transport::sendMessage)
279				.onErrorComplete(t -> {
280					logger.warn("Issue sending response to the agent, ", t);
281					return true;
282				})
283				.subscribe();
284		}
285	
286		/** Queues a notification for in-order delivery by the notification drain. */
287		private void enqueue(AcpSchema.JSONRPCNotification notification) {
288			logger.debug("Received notification method={}", notification.method());
289			logger.trace("Incoming notification method='{}' params={}", notification.method(), notification.params());
290			Sinks.EmitResult result = this.notifications.offer(notification);
291			if (!result.isFailure()) {
292				return;
293			}
294			if (result == Sinks.EmitResult.FAIL_TERMINATED || result == Sinks.EmitResult.FAIL_CANCELLED
295					|| this.notifications.isCompleting()) {
296				// The session is shutting down. Refusing newly arriving notifications
297				// is the intended behaviour: a graceful shutdown stops accepting new
298				// work and drains what is already queued, and JSON-RPC notifications
299				// carry no delivery guarantee by design.
300				logger.debug("Session is closing; dropping notification method='{}' ({})", notification.method(),
301						result);
302			}
303			else {
304				// Overflow, no subscriber, or concurrent (non-serialized) emission:
305				// protocol traffic lost on a live session, which is never expected.
306				logger.error("Dropped notification method='{}': sink emission failed with {}", notification.method(),
307						result);
308			}
309		}
