311		/**
312		 * Handles an incoming JSON-RPC request by routing it to the appropriate handler.
313		 * @param request The incoming JSON-RPC request
314		 * @return A Mono containing the JSON-RPC response
315		 */
316		private Mono<AcpSchema.JSONRPCResponse> handleIncomingRequest(AcpSchema.JSONRPCRequest request) {
317			return Mono.defer(() -> {
318				var handler = this.requestHandlers.get(request.method());
319				if (handler == null) {
320					MethodNotFoundError error = getMethodNotFoundError(request.method());
321					logger.warn("No handler registered for request method '{}': {} - {}",
322							request.method(), error.message(),
323							error.data() != null ? error.data() : "register a handler to support this operation");
324					logger.trace("Available handlers: {}", this.requestHandlers.keySet());
325					return Mono.just(InboundMessages.error(request, AcpErrorCodes.METHOD_NOT_FOUND, error.message(),
326							error.data()));
327				}
328	
329				logger.debug("Invoking handler for method '{}'", request.method());
330				logger.trace("Handler params for '{}': {}", request.method(), request.params());
331				return InboundMessages.requireResult(HandlerFailures.invoke(() -> handler.handle(InboundMessages.paramsOrEmpty(request.params()))),
332						request.method())
333					.doOnSuccess(result -> logger.debug("Handler for '{}' completed successfully", request.method()))
334					.doOnError(error -> logger.debug("Handler for '{}' threw error: {}", request.method(), error.getMessage()))
335					.map(result -> InboundMessages.result(request, result));
336			});
337		}
338	
339		record MethodNotFoundError(String method, String message, @Nullable Object data) {
340		}
341	
342		private MethodNotFoundError getMethodNotFoundError(String method) {
343			// ACP-specific error messages for unsupported client methods
344			switch (method) {
345				case AcpSchema.METHOD_FS_READ_TEXT_FILE:
346					return new MethodNotFoundError(method, "File system read not supported",
347							Map.of("reason", "Client does not have fs.readTextFile capability"));
348				case AcpSchema.METHOD_FS_WRITE_TEXT_FILE:
349					return new MethodNotFoundError(method, "File system write not supported",
350							Map.of("reason", "Client does not have fs.writeTextFile capability"));
351				case AcpSchema.METHOD_SESSION_REQUEST_PERMISSION:
352					return new MethodNotFoundError(method, "Permission request not supported",
353							Map.of("reason", "No requestPermissionHandler registered - use --yolo flag or register a handler"));
354				case AcpSchema.METHOD_TERMINAL_CREATE:
355				case AcpSchema.METHOD_TERMINAL_OUTPUT:
356				case AcpSchema.METHOD_TERMINAL_RELEASE:
357				case AcpSchema.METHOD_TERMINAL_WAIT_FOR_EXIT:
358				case AcpSchema.METHOD_TERMINAL_KILL:
359					return new MethodNotFoundError(method, "Terminal not supported",
360							Map.of("reason", "Client does not have terminal capability"));
361				default:
362					return new MethodNotFoundError(method, "Method not found: " + method, null);
363			}
364		}
