367		 * Handles an incoming JSON-RPC notification by routing it to the appropriate handler.
368		 * @param notification The incoming JSON-RPC notification
369		 * @return A Mono that completes when the notification is processed
370		 */
371		private Mono<Void> handleIncomingNotification(AcpSchema.JSONRPCNotification notification) {
372			return Mono.defer(() -> {
373				return InboundMessages.deliver(logger, notification, this.notificationHandlers, NotificationHandler::handle);
374			});
375		}
