420		/**
421		 * Answers every {@code session/request_permission} request of a session the agent is still
422		 * waiting on with the {@code cancelled} outcome, and stops its handler; the client calls this
423		 * when it sends {@code session/cancel} for the session (ACP v1, prompt turn, Cancellation).
424		 * @param sessionId the session whose prompt turn is being cancelled
425		 * @return how many requests were answered
426		 */
427		public int cancelPermissionRequests(String sessionId) {
428			return this.inbound.answer(AcpSchema.METHOD_SESSION_REQUEST_PERMISSION, sessionId,
429					request -> InboundMessages.result(request,
430							new AcpSchema.RequestPermissionResponse(new AcpSchema.PermissionCancelled())));
