432	
433		/**
434		 * Closes the session gracefully, allowing pending operations to complete.
435		 * @return A Mono that completes when the session is closed
436		 */
437		@Override
438		public Mono<Void> closeGracefully() {
439			return Mono.<Void>fromRunnable(() -> {
440				this.closing = true;
441				this.inbound.cancelAll();
442				dismissPendingResponses();
443				// Never lost to a notification being delivered concurrently (NotificationQueue).
444				this.notifications.complete();
445			})
446				// Wait for queued notifications to drain before tearing the session down;
447				// disposing immediately would discard them. Bounded so a handler that never
448				// completes cannot hang graceful close.
449				.then(this.notificationDrainTerminated.asMono()
450					.timeout(this.requestTimeout, Mono.empty(), this.timeoutScheduler))
451				.doFinally(signal -> {
452					notificationSubscription.dispose();
453				});
454		}
455	
456		/**
457		 * Closes the session immediately, potentially interrupting pending operations.
458		 */
459		@Override
460		public void close() {
461			this.closing = true;
462			this.inbound.cancelAll();
463			dismissPendingResponses();
464			this.notifications.complete();
465			notificationSubscription.dispose();
466			// A response held behind a notification still being handled completes now.
467			this.notifications.releaseHeld();
468		}
