195		/**
196		 * Handles an incoming JSON-RPC message and returns an optional response message.
197		 * @param message The incoming message
198		 * @return A Mono containing the response message, or empty for notifications
199		 */
200		private Mono<AcpSchema.JSONRPCMessage> handle(AcpSchema.JSONRPCMessage message) {
201			if (message instanceof AcpSchema.JSONRPCResponse response) {
202				this.outbound.complete(response);
203				return Mono.empty();
204			}
205			if (message instanceof AcpSchema.JSONRPCRequest request) {
206				logger.debug("Received request method={} id={}", request.method(), request.id());
207				// Mono.from widens the response Mono to the message type without an operator.
208				// The whole answer is tracked, so a $/cancel_request races it inside one Mono.
209				AtomicReference<ActivePrompts.@Nullable Turn> promptTurn = new AtomicReference<>();
210				return Mono.from(this.inbound
211					.track(request, handleIncomingRequest(request, promptTurn),
212							() -> whenCancelled(request, promptTurn.get()))
213					.onErrorResume(error -> Mono.just(InboundMessages.error(request, error))));
214			}
215			if (message instanceof AcpSchema.JSONRPCNotification notification) {
216				logger.debug("Received notification method={}", notification.method());
217				return handleIncomingNotification(notification).then(Mono.empty());
218			}
219			logger.warn("Received unknown message type: {}", message.getClass().getName());
220			return Mono.empty();
221		}
222	
223		/**
224		 * Handles an incoming JSON-RPC request by routing it to the appropriate handler.
225		 * For session/prompt requests, enforces single-turn semantics.
226		 * @param request The incoming JSON-RPC request
227		 * @return A Mono containing the JSON-RPC response
228		 */
229		private Mono<AcpSchema.JSONRPCResponse> handleIncomingRequest(AcpSchema.JSONRPCRequest request,
230				AtomicReference<ActivePrompts.@Nullable Turn> promptTurn) {
231			return Mono.defer(() -> {
232				var handler = this.requestHandlers.get(request.method());
233				if (handler == null) {
234					MethodNotFoundError error = getMethodNotFoundError(request.method());
235					return Mono.just(InboundMessages.error(request, AcpErrorCodes.METHOD_NOT_FOUND, error.message(),
236							error.data()));
237				}
238	
239				// Single-turn enforcement for session/prompt requests
240				if (AcpSchema.METHOD_SESSION_PROMPT.equals(request.method())) {
241					String sessionId = extractSessionId(request.params());
242					ActivePrompts.Turn turn = activePrompts.tryStart(sessionId, request.id());
243					if (turn == null) {
244						// -32600, not -32000: ACP v1 defines -32000 as "Authentication required".
245						return Mono.just(InboundMessages.error(request, AcpErrorCodes.INVALID_REQUEST,
246								"There is already an active prompt on session " + sessionId,
247								Map.of("sessionId", sessionId)));
248					}
249					promptTurn.set(turn);
250	
251					// The turn ends before the response is published (#14): see
252					// ActivePrompts.endBeforePublishing. Mono.defer keeps a handler that throws
253					// synchronously from holding the turn forever: the throw becomes an error
254					// signal that passes through the release.
255					// The deadlines may answer instead of the handler; either answer passes
256					// through the release.
257					// Once session/cancel was received, the prompt answers stop reason cancelled,
258					// whatever its handler returns or fails with (ACP v1, prompt turn, Cancellation).
259					return activePrompts.endBeforePublishing(turn, promptDeadlines.answer(turn, request,
260							InboundMessages.requireResult(HandlerFailures.invoke(() -> handler.handle(InboundMessages.paramsOrEmpty(request.params()))),
261									request.method())
262								.map(result -> InboundMessages.result(request, cancelledIfCancelling(turn, request, result)))
263								.onErrorResume(error -> turn.answer().isCancelling(),
264										error -> Mono.just(cancelledPromptAfterFailure(request, error)))));
265				}
266	
267				Mono<AcpSchema.JSONRPCResponse> response = InboundMessages
268					.requireResult(HandlerFailures.invoke(() -> handler.handle(InboundMessages.paramsOrEmpty(request.params()))),
269							request.method())
270					.map(result -> InboundMessages.result(request, result));
271				if (AcpSchema.METHOD_SESSION_CLOSE.equals(request.method())) {
272					return cancelOngoingWork(extractSessionId(request.params())).then(response);
273				}
274				return response;
275			});
276		}
277	
278		/**
279		 * Cancels a closing session's ongoing work as if session/cancel had been received (ACP
280		 * v1, CloseSessionRequest: the agent must cancel any ongoing work related to the
281		 * session, treating it as if session/cancel was called, and then free its resources):
282		 * the session/cancel handler is told, and an active prompt is cancelled and answers
283		 * cancelled. Completes once that prompt's turn has ended, so the close handler frees
284		 * the session after its work has stopped.
285		 */
286		private Mono<Void> cancelOngoingWork(String sessionId) {
287			ActivePrompts.Turn turn = this.activePrompts.current(sessionId);
288			this.activePrompts.cancel(sessionId);
289			Mono<Void> cancelHandler = Mono.empty();
290			if (this.notificationHandlers.containsKey(AcpSchema.METHOD_SESSION_CANCEL)) {
291				cancelHandler = InboundMessages.deliver(logger,
292						new AcpSchema.JSONRPCNotification(AcpSchema.JSONRPC_VERSION, AcpSchema.METHOD_SESSION_CANCEL,
293								Map.of("sessionId", sessionId)),
294						this.notificationHandlers, NotificationHandler::handle);
295			}
296			return turn == null ? cancelHandler : cancelHandler.then(turn.ended());
297		}
298	
299		/**
300		 * The answer to a request a $/cancel_request cancelled: -32800, except for a prompt
301		 * already cancelled by session/cancel, which must answer stop reason cancelled (ACP v1,
302		 * prompt turn, Cancellation).
303		 */
304		private static AcpSchema.JSONRPCResponse whenCancelled(AcpSchema.JSONRPCRequest request,
305				ActivePrompts.@Nullable Turn promptTurn) {
306			if (promptTurn != null && promptTurn.answer().isCancelling()) {
307				return cancelledPrompt(request);
308			}
309			return InboundRequests.cancelled(request);
310		}
311	
312		private static AcpSchema.JSONRPCResponse cancelledPrompt(AcpSchema.JSONRPCRequest request) {
313			return InboundMessages.result(request, new AcpSchema.PromptResponse(AcpSchema.StopReason.CANCELLED));
314		}
315	
316		/**
317		 * A prompt handler's answer, with stop reason {@code cancelled} once session/cancel was
318		 * received for the prompt: the agent must then answer cancelled (ACP v1, prompt turn,
319		 * Cancellation), also when its handler returned another stop reason. {@code _meta} is kept.
320		 */
321		private static Object cancelledIfCancelling(ActivePrompts.Turn turn, AcpSchema.JSONRPCRequest request,
322				Object result) {
323			if (turn.answer().isCancelling() && result instanceof AcpSchema.PromptResponse response
324					&& !AcpSchema.StopReason.CANCELLED.equals(response.stopReason())) {
325				logger.debug("Prompt {} answered {} after session/cancel; sending cancelled", request.id(),
326						response.stopReason());
327				return new AcpSchema.PromptResponse(AcpSchema.StopReason.CANCELLED, response.meta());
328			}
329			return result;
330		}
331	
332		/**
333		 * The answer to a prompt whose handler failed after session/cancel: stop reason
334		 * {@code cancelled}, whatever the failure (ACP v1, prompt turn, Cancellation: agents must
335		 * catch the errors aborted work raises and answer cancelled). The failure is logged here.
336		 */
337		private static AcpSchema.JSONRPCResponse cancelledPromptAfterFailure(AcpSchema.JSONRPCRequest request,
338				Throwable error) {
339			logger.debug("Prompt {} failed after session/cancel; answering cancelled", request.id(), error);
340			return cancelledPrompt(request);
341		}
