343		/**
344		 * Extracts the sessionId from request parameters, which arrive as a {@code Map} from
345		 * the JSON transports and as the typed record from in-process transports.
346		 */
347		private String extractSessionId(@Nullable Object params) {
348			// The typed records come from in-process callers, which no nullness checker may
349			// have seen; a null key would fail the activePrompts map.
350			if (params instanceof AcpSchema.PromptRequest promptRequest) {
351				return promptRequest.sessionId() != null ? promptRequest.sessionId() : "unknown";
352			}
353			if (params instanceof AcpSchema.CancelNotification cancelNotification) {
354				return cancelNotification.sessionId() != null ? cancelNotification.sessionId() : "unknown";
355			}
356			if (params instanceof AcpSchema.CloseSessionRequest closeSessionRequest) {
357				return closeSessionRequest.sessionId() != null ? closeSessionRequest.sessionId() : "unknown";
358			}
359			if (params instanceof Map<?, ?> map) {
360				Object sessionId = map.get("sessionId");
361				return sessionId != null ? sessionId.toString() : "unknown";
362			}
363			return "unknown";
364		}
