373		/**
374		 * Handles an incoming JSON-RPC notification by routing it to the appropriate handler.
375		 * A session/cancel notification does not end the active prompt's turn: the cancelled
376		 * prompt's response does (see ActivePrompts#cancel). A $/cancel_request cancels the
377		 * request it names, which is then answered with -32800 unless it already answered; a
378		 * cancelled prompt's turn ends before that answer is published.
379		 * @param notification The incoming JSON-RPC notification
380		 * @return A Mono that completes when the notification is processed
381		 */
382		private Mono<Void> handleIncomingNotification(AcpSchema.JSONRPCNotification notification) {
383			return Mono.defer(() -> {
384				// $/cancel_request: answered by the session itself, never by a handler
385				if (AcpSchema.METHOD_CANCEL_REQUEST.equals(notification.method())) {
386					this.inbound.cancel(notification);
387					return Mono.empty();
388				}
389	
390				// session/cancel: the turn stays until the cancelled prompt answers
391				if (AcpSchema.METHOD_SESSION_CANCEL.equals(notification.method())) {
392					activePrompts.cancel(extractSessionId(notification.params()));
393				}
394	
395				return InboundMessages.deliver(logger, notification, this.notificationHandlers, NotificationHandler::handle);
396			});
397		}
