 27	/**
 28	 * The requests and notifications a session sends to its peer, the same way for both session
 29	 * sides: request ids, the requests still waiting for a response, the request timeout, and
 30	 * failing fast once the transport can no longer deliver.
 31	 */
 32	final class OutboundMessages {
 33	
 34		private static final Logger logger = LoggerFactory.getLogger(OutboundMessages.class);
 35	
 36		private final AcpTransport transport;
 37	
 38		private final Duration requestTimeout;
 39	
 40		/** The reason the transport cannot deliver (it failed to connect or start, or terminated), or null. */
 41		private final Supplier<@Nullable Throwable> transportFailure;
 42	
 43		/** Wraps the transport failure into the error a caller receives. */
 44		private final Function<Throwable, RuntimeException> unavailable;
 45	
 46		/** Requests waiting for a response, keyed by request id. */
 47		private final PendingResponses pendingResponses;
 48	
 49		/** When a response that arrived may complete its caller. */
 50		private final ResponseOrder responseOrder;
 51	
 52		/** Session-specific prefix for request ids. */
 53		private final String idPrefix = UUID.randomUUID().toString().substring(0, 8);
 54	
 55		private final AtomicLong requestCounter = new AtomicLong(0);
 56	
 57		OutboundMessages(AcpTransport transport, Duration requestTimeout, Supplier<@Nullable Throwable> transportFailure,
 58				Function<Throwable, RuntimeException> unavailable, String peer) {
 59			this(transport, requestTimeout, transportFailure, unavailable, peer, ResponseOrder.IMMEDIATE);
 60		}
 61	
 62		OutboundMessages(AcpTransport transport, Duration requestTimeout, Supplier<@Nullable Throwable> transportFailure,
 63				Function<Throwable, RuntimeException> unavailable, String peer, ResponseOrder responseOrder) {
 64			this.transport = transport;
 65			this.responseOrder = responseOrder;
 66			this.requestTimeout = requestTimeout;
 67			this.transportFailure = transportFailure;
 68			this.unavailable = unavailable;
 69			this.pendingResponses = new PendingResponses(transportFailure, unavailable, peer);
 70		}
 71	
 72		/**
 73		 * Sends a request and waits, at most the request timeout, for its response. An error
 74		 * response fails the returned Mono with {@link AcpError}. A response that arrived
 75		 * completes the Mono when the {@link ResponseOrder} lets it, within the same timeout.
 76		 */
 77		<T> Mono<T> sendRequest(String method, Object params, TypeRef<T> typeRef) {
 78			return sendRequest(method, params, typeRef, this.requestTimeout);
 79		}
 80	
 81		/**
 82		 * Sends a request and waits, at most {@code timeout}, for its response; with a null
 83		 * {@code timeout} it waits until the response arrives, the caller disposes the request, or
 84		 * the transport fails. Otherwise as {@link #sendRequest(String, Object, TypeRef)}.
 85		 */
 86		<T> Mono<T> sendRequest(String method, Object params, TypeRef<T> typeRef, @Nullable Duration timeout) {
 87			Mono<AcpSchema.JSONRPCResponse> response = Mono.deferContextual(ctx -> {
 88				// One id per subscription: a resubscribed request (a retry) is a new request.
 89				String requestId = this.idPrefix + "-" + this.requestCounter.getAndIncrement();
 90				long sentAt = this.responseOrder.position();
 91				Runnable answered = this.responseOrder.awaiting(sentAt);
 92				// Completes once the request is handed to the transport; a $/cancel_request
 93				// waits for it, so it never overtakes its request on an ordered transport.
 94				Sinks.Empty<Void> written = Sinks.empty();
 95				// At most one $/cancel_request per request, whether the caller disposed it or a
 96				// RequestCancellation trigger fired.
 97				AtomicBoolean cancelSent = new AtomicBoolean();
 98				Runnable cancel = () -> {
 99					if (cancelSent.compareAndSet(false, true)) {
100						cancelRequest(requestId, written.asMono());
101					}
102				};
103				Disposable.Swap gracefulCancel = Disposables.swap();
104				return Mono.<AcpSchema.JSONRPCResponse>create(responseSink -> {
105					if (!this.pendingResponses.register(requestId, responseSink, cancel)) {
106						return;
107					}
108					logger.debug("Sending request for method {} with id {}", method, requestId);
109					logger.trace("Outgoing request method='{}' id={} params={}", method, requestId, params);
110					AcpSchema.JSONRPCRequest request = new AcpSchema.JSONRPCRequest(AcpSchema.JSONRPC_VERSION, requestId,
111							method, params);
112					this.transport.sendMessage(request).contextWrite(ctx).subscribe(v -> {
113					}, error -> {
114						written.tryEmitError(error);
115						this.pendingResponses.abandon(requestId, responseSink);
116						responseSink.error(error);
117					}, written::tryEmitEmpty);
118					Object trigger = ctx.getOrDefault(RequestCancellation.KEY, null);
119					if (trigger instanceof Publisher<?> publisher) {
120						gracefulCancel.update(cancelOn(publisher, requestId, cancel));
121					}
122				}).doFinally(signal -> {
123					gracefulCancel.dispose();
124					answered.run();
125				})
126					.flatMap(answer -> this.responseOrder.after(sentAt, answer));
127			});
128			return withTimeout(response, timeout)
129				.handle((answer, resultSink) -> deliver(method, answer, typeRef, resultSink));
130		}
131	
132		private static <R> Mono<R> withTimeout(Mono<R> response, @Nullable Duration timeout) {
133			return (timeout != null) ? AcpSchedulers.withTimeout(response, timeout) : response;
134		}
135	
136		/** Runs {@code cancel} when a RequestCancellation trigger fires while the request still waits. */
137		private Disposable cancelOn(Publisher<?> trigger, String requestId, Runnable cancel) {
138			return Flux.from(trigger).take(1).then().subscribe(v -> {
139			}, error -> logger.debug("Ignored a failed cancel trigger for request {}", requestId), () -> {
140				if (this.pendingResponses.isPending(requestId)) {
141					cancel.run();
142				}
143			});
144		}
145	
146		private <T> void deliver(String method, AcpSchema.JSONRPCResponse response, TypeRef<T> typeRef,
147				SynchronousSink<T> resultSink) {
148			AcpSchema.JSONRPCError error = response.error();
149			if (error != null) {
150				// The caller's failure is the report; the error's data is the peer's payload.
151				logger.debug("Request {} failed with peer error {}", method, error.code());
152				resultSink.error(new AcpError(error));
153			}
154			else if (typeRef.getType().equals(Void.class)) {
155				resultSink.complete();
156			}
157			else {
158				ResponseResults.deliver(method, response.result(), typeRef, this.transport, resultSink);
159			}
160		}
161	
162		/**
163		 * Tells the peer that the caller gave up on a request (ACP v1 {@code $/cancel_request}):
164		 * its subscription was cancelled, by the caller or by its timeout, before a response.
165		 * Sent once the request itself has been handed to the transport, and not at all if that
166		 * failed. Fire and forget: the transport may be why the caller gave up.
167		 */
168		private void cancelRequest(String requestId, Mono<Void> written) {
169			written.then(sendNotification(AcpSchema.METHOD_CANCEL_REQUEST, new AcpSchema.CancelRequestNotification(requestId)))
170				// Off the thread that cancelled, which may be the shared timeout timer: the
171				// transport's emission can wait for a busy outbound sink.
172				.subscribeOn(AcpSchedulers.timeoutDelivery())
173				.subscribe(v -> {
174				}, error -> logger.debug("No $/cancel_request sent for id {}: {}", requestId, error.getMessage()),
175						() -> logger.debug("Sent $/cancel_request for id {}", requestId));
176		}
177	
178		/** Sends a notification, or fails at once when the transport cannot deliver. */
179		Mono<Void> sendNotification(String method, @Nullable Object params) {
180			return Mono.defer(() -> {
181				Throwable failure = this.transportFailure.get();
182				if (failure != null) {
183					return Mono.error(this.unavailable.apply(failure));
184				}
185				return this.transport
186					.sendMessage(new AcpSchema.JSONRPCNotification(AcpSchema.JSONRPC_VERSION, method, params));
187			});
188		}
189	
190		/** Completes the request this response answers. */
191		void complete(AcpSchema.JSONRPCResponse response) {
192			this.pendingResponses.complete(response);
193		}
194	
195		/** Fails every request still waiting for a response. */
196		void dismissPending(@Nullable Throwable cause) {
197			this.pendingResponses.dismissAll(cause);
198		}
199	
200		/** The number of requests waiting for a response. */
201		int pendingRequests() {
202			return this.pendingResponses.size();
203		}
