222	/**
223	 * Moves ACP's JSON-RPC messages between this side of a connection and its peer. A transport
224	 * carries one connection: it writes the messages the SDK sends and hands the SDK every
225	 * message that arrives. An application chooses an implementation and passes it to a client or
226	 * agent builder; after that it calls the transport at most to close it or to wait for its end.
227	 *
228	 * <p>Two interfaces extend it, one per side: {@link AcpClientTransport} for a client and
229	 * {@link AcpAgentTransport} for an agent. The protocol session that the builder puts on top of
230	 * the transport owns everything else JSON-RPC needs: request ids, pending responses, timeouts
231	 * and handler dispatch.
232	 *
233	 * <p>Implementations must accept {@link #sendMessage} from several threads at once: the
234	 * session answers the peer's requests on the thread that reads them while user threads send
235	 * their own requests and notifications. {@link #unmarshalFrom} must report a value that does
236	 * not fit the requested type with an {@link IllegalArgumentException}, which
237	 * {@link #unmarshalParams} turns into an Invalid params error.
238	 *
239	 * @author Mark Pollack
240	 * @author Christian Tzolov
241	 */
242	public interface AcpTransport {
243	
244		/**
245		 * Closes the transport without reporting the outcome; {@link #closeGracefully()} is the
246		 * variant to wait on. The interface's default subscribes to {@link #closeGracefully()}
247		 * and returns when that subscription returns: at once when the implementation closes
248		 * asynchronously, and only after the close when it does the work on the subscribing
249		 * thread. A failed close is logged at WARN by this interface's logger.
250		 */
251		default void close() {
252			this.closeGracefully()
253				.subscribe(ignored -> {
254				}, error -> LoggerFactory.getLogger(AcpTransport.class)
255					.warn("Closing the transport failed: {}", error.toString(), error));
256		}
257	
258		/**
259		 * Closes the transport: stops reading from and writing to the peer, and releases the
260		 * threads, streams or network connections it holds. What it waits for differs per
261		 * implementation; the stdio client, for example, gives the agent process time to exit.
262		 * The shipped transports can be closed more than once, with this method and
263		 * {@link #close()} in either order: only the first call closes.
264		 * @return a Mono that completes when the transport is closed
265		 */
266		Mono<Void> closeGracefully();
267	
268		/**
269		 * Sends one JSON-RPC message, a request, response or notification, to the peer. When the
270		 * returned Mono completes depends on the implementation: once the message is queued for
271		 * writing (stdio, WebSocket), or once the peer has accepted it (Streamable HTTP, which
272		 * posts it and waits for the HTTP answer).
273		 * @param message the message to send
274		 * @return a Mono that completes when the message has been handed on, or errors when it
275		 * cannot be sent
276		 */
277		Mono<Void> sendMessage(JSONRPCMessage message);
278	
279		/**
280		 * Converts a value read from JSON, such as a message's params or a response's result, to
281		 * the given type with this transport's JSON mapper.
282		 * @param <T> the type to convert to
283		 * @param data the value as read from JSON, usually a map
284		 * @param typeRef the type to convert to
285		 * @return the value as that type
286		 * @throws IllegalArgumentException if the value does not fit the type
287		 */
288		<T> T unmarshalFrom(Object data, TypeRef<T> typeRef);
289	
290		/**
291		 * Reads the params of an inbound request or notification as the method's params type, and
292		 * checks that the {@link AcpSchema} records in them carry every field the ACP schema
293		 * requires. Params of the wrong shape are the peer's mistake, not an internal error: they
294		 * fail with JSON-RPC error -32602 (Invalid params), which the session sends back when they
295		 * belong to a request. An application's own params types, such as an extension method's,
296		 * are converted but not checked.
297		 * @param <T> the params type
298		 * @param params the params as received
299		 * @param typeRef the method's params type
300		 * @return the params as that type
301		 * @throws AcpProtocolException if the params cannot be converted to the type or a required
302		 * field is missing; its code is {@link AcpErrorCodes#INVALID_PARAMS}
303		 */
304		default <T> T unmarshalParams(Object params, TypeRef<T> typeRef) {
305			T value;
306			try {
307				value = unmarshalFrom(params, typeRef);
308			}
309			catch (IllegalArgumentException e) {
310				throw new AcpProtocolException(AcpErrorCodes.INVALID_PARAMS, "Invalid params", firstLine(e.getMessage()));
311			}
312			String missing = RequiredFields.firstMissing(value);
313			if (missing != null) {
314				throw new AcpProtocolException(AcpErrorCodes.INVALID_PARAMS, "Invalid params",
315						"missing required field: " + missing);
316			}
317			return value;
318		}
319	
320		private static @Nullable String firstLine(@Nullable String message) {
321			if (message == null) {
322				return null;
323			}
324			int end = message.indexOf('\n');
325			return end < 0 ? message : message.substring(0, end);
326		}
327	
328		/**
329		 * Returns the ACP protocol versions this transport supports. The SDK does not read it when
330		 * it negotiates a version: a client sends the version its {@code initialize} call names.
331		 * The interface's default returns only {@link AcpSchema#LATEST_PROTOCOL_VERSION}.
332		 * @return the supported protocol versions
333		 */
334		default List<Integer> protocolVersions() {
335			return List.of(AcpSchema.LATEST_PROTOCOL_VERSION);
336		}
337	
338	}
