343	package com.agentclientprotocol.sdk.spec;
344	
345	import org.jspecify.annotations.Nullable;
346	
347	/**
348	 * ACP's rule for extension methods, the custom requests and notifications two peers agree on
349	 * outside the protocol: the method name must start with an underscore ({@code _}), such as
350	 * {@code _example.com/workspace/buffers} (ACP v1, Extensibility). Every extension API of the SDK
351	 * checks names with {@link #requireExtension}: the builders' {@code extRequestHandler} and
352	 * {@code extNotificationHandler}, the facades' {@code sendExtRequest} and
353	 * {@code sendExtNotification}, and the {@code @ExtRequest} and {@code @ExtNotification} annotations
354	 * when an annotated agent is built. So a custom handler can never replace a protocol method, and a
355	 * custom send can never pass for one. Applications call it only to check a name themselves.
356	 *
357	 * <p>How the SDK treats extension methods, the same on both sides:
358	 * <ul>
359	 * <li>A request no handler serves is answered "Method not found" ({@code -32601}); a notification
360	 * no handler serves is ignored, as ACP asks, and logged at DEBUG only.</li>
361	 * <li>Params the peer omitted arrive as an empty object. Params that cannot be read as the
362	 * handler's params type are answered "Invalid params" ({@code -32602}) for a request; for a
363	 * notification the failure is logged and the notification dropped.</li>
364	 * <li>A request handler must produce a result: one that produces none (an empty {@code Mono}, or
365	 * {@code null}) is answered with an internal error ({@code -32603}). Answer with an empty map when
366	 * there is nothing to return.</li>
367	 * <li>When the peer answers {@code "result": null}, the sender's {@code Mono} completes empty and
368	 * the sync API returns {@code null}.</li>
369	 * <li>They are outside ACP's lifecycle: the SDK does not wait for {@code initialize} before sending
370	 * or serving them, and checks no capability. ACP asks peers to advertise their extensions in the
371	 * {@code _meta} of their capabilities.</li>
372	 * </ul>
373	 *
374	 * @author Mark Pollack
375	 */
376	public final class ExtensionMethods {
377	
378		/** The prefix ACP reserves for extension method names: {@value}. */
379		public static final String PREFIX = "_";
380	
381		private ExtensionMethods() {
382		}
383	
384		/**
385		 * Returns whether a method name is an extension method name.
386		 * @param method the method name, or {@code null}
387		 * @return true if it starts with {@value #PREFIX}; false for {@code null}
388		 */
389		public static boolean isExtension(@Nullable String method) {
390			return method != null && method.startsWith(PREFIX);
391		}
392	
393		/**
394		 * Checks that a method name is an extension method name.
395		 * @param method the method name
396		 * @return the method name, unchanged
397		 * @throws IllegalArgumentException if it is null or does not start with {@value #PREFIX}
398		 */
399		public static String requireExtension(@Nullable String method) {
400			if (method == null || !isExtension(method)) {
401				throw new IllegalArgumentException("Extension method names must start with '" + PREFIX
402						+ "' (ACP reserves the other names for the protocol): " + method);
403			}
404			return method;
405		}
406	
407	}
