414	import org.reactivestreams.Publisher;
415	import reactor.util.context.Context;
416	import reactor.util.context.ContextView;
417	
418	/**
419	 * Cancels a request the SDK sends while still waiting for the peer's answer: write
420	 * {@link #cancelWhen} into the request's Reactor context, and when its trigger fires the SDK sends
421	 * {@code $/cancel_request} for the request, which then ends with whatever the peer answers. Use it
422	 * when the answer still matters after cancelling, for example to see whether the work finished
423	 * first; to give up on a request at once, dispose its subscription instead. It works with the
424	 * request methods of the asynchronous API: {@code AcpAsyncClient} on the client side,
425	 * {@code AcpAsyncAgent} and {@code PromptContext} on the agent side. ACP v1 calls this graceful
426	 * cancellation ("the calling side MAY implement graceful cancellation processing by waiting for the
427	 * response").
428	 *
429	 * <p>When the trigger emits a value or completes while the request waits for its answer, the
430	 * session sends {@code $/cancel_request} once the request has been written, and keeps waiting. The
431	 * request then ends with the peer's answer: its result, or an {@link AcpError} with code
432	 * {@code -32800} ({@code AcpErrorCodes.REQUEST_CANCELLED}). A Java peer cancels the handler and
433	 * answers {@code -32800} unless the handler answered first; for a {@code session/prompt} that the
434	 * agent is already cancelling under {@code session/cancel}, it answers stop reason
435	 * {@code cancelled} instead. If the peer never answers, the request still ends at its timeout, if
436	 * it has one. A trigger that fails is ignored and cancels nothing. Every request sent within the
437	 * subscription that carries the context is cancelled on the trigger, and at most one
438	 * {@code $/cancel_request} is sent per request, whichever way it is cancelled.
439	 *
440	 * <p>Disposing a request's subscription, directly or through a timeout, also sends
441	 * {@code $/cancel_request}, but stops listening: the peer's answer is discarded. To stop a prompt
442	 * turn the way ACP intends, with {@code session/cancel}, pass a
443	 * {@link com.agentclientprotocol.sdk.client.CancellationSignal} to the client's
444	 * {@code prompt(request, stop)} (async or sync), or call {@code AcpAsyncClient.cancel(..)};
445	 * this class cancels any one request, in either direction. The sync API cannot carry a trigger:
446	 * {@code AcpSyncClient.async()} gives the asynchronous client to use it with.
447	 *
448	 * <pre>{@code
449	 * Sinks.Empty<Void> stop = Sinks.empty();
450	 * Mono<AcpSchema.PromptResponse> answer = client.prompt(request)
451	 *     .contextWrite(RequestCancellation.cancelWhen(stop.asMono()));
452	 * // when the user presses Stop:
453	 * stop.tryEmitEmpty();
454	 * }</pre>
455	 */
456	public final class RequestCancellation {
457	
458		/** The context key of the cancel trigger. */
459		static final Object KEY = RequestCancellation.class;
460	
461		private RequestCancellation() {
462		}
463	
464		/**
465		 * Returns a Reactor context that cancels every request sent under it, gracefully, when
466		 * {@code trigger} emits its first value or completes.
467		 * @param trigger the cancel trigger, any Reactive Streams publisher, such as a {@code Mono} or
468		 * a {@code Sinks.Empty}'s {@code asMono()}; must not be null
469		 * @return the context, for {@code contextWrite}
470		 */
471		public static ContextView cancelWhen(Publisher<?> trigger) {
472			return Context.of(KEY, trigger);
473		}
474	
475	}

