251	   251		 * {@code _meta}. The capabilities and client info still come from the builder; this overload
252	   252		 * exists for {@code _meta} and for testing version negotiation, not for advertising
253	   253		 * capabilities.
254	   254		 * @param protocolVersion the protocol version to announce; this SDK speaks
255	   255		 * {@value AcpSchema#LATEST_PROTOCOL_VERSION}
256	   256		 * @param meta the request's {@code _meta}, or {@code null}
257	   257		 * @return a {@code Mono} emitting the agent's answer
258	   258		 * @see #initialize()
259	   259		 */
260	   260		public Mono<AcpSchema.InitializeResponse> initialize(int protocolVersion, @Nullable Map<String, Object> meta) {
261	   261			AcpSchema.InitializeRequest initializeRequest = new AcpSchema.InitializeRequest(protocolVersion,
262	   262					this.clientCapabilities, this.clientInfo, meta);
263	   263			logger.debug("Initializing ACP client with protocol version: {}", protocolVersion);
264	   264			return Mono.fromRunnable(() -> advertisedCapabilities.set(this.clientCapabilities))
265	   265				.then(Mono.defer(
266	   266						() -> session.sendRequest(AcpSchema.METHOD_INITIALIZE, initializeRequest, INITIALIZE_RESPONSE_TYPE_REF)))
267	   267				.flatMap(response -> {
268	   268					// ACP v1, initialization, Version Negotiation: an answer with a version this client
269	   269					// does not speak closes the connection; nothing of the answer is kept.
270	   270					Integer answered = response.protocolVersion();
271	   271					if (answered == null || answered != AcpSchema.LATEST_PROTOCOL_VERSION) {
272	   272						int agentVersion = (answered != null) ? answered : -1;
273	   273						logger.warn("The agent answered initialize with protocol version {}; this client speaks {}. "
274	   274								+ "Closing the connection.", agentVersion, AcpSchema.LATEST_PROTOCOL_VERSION);
275	   275						return closeGracefully().onErrorComplete()
276	   276							.then(Mono.error(new AcpVersionException(agentVersion, AcpSchema.LATEST_PROTOCOL_VERSION)));
277	   277					}
278	   278					// Store the negotiated agent capabilities
279	   279					NegotiatedCapabilities caps = NegotiatedCapabilities.fromAgent(response.agentCapabilities());
280	   280					agentCapabilities.set(caps);
281	   281					authMethods.set((response.authMethods() != null) ? List.copyOf(response.authMethods()) : List.of());
282	   282					logger.debug("Negotiated agent capabilities: {}", caps);
283	   283					return Mono.just(response);
284	   284				});
285	   285		}
