560	   560		/**
561	   561		 * Sends a prompt to a session ({@code session/prompt}) and returns the agent's answer at the
562	   562		 * end of the turn, with the stop reason. Meanwhile the agent streams the turn as
563	   563		 * {@code session/update} notifications to the session update handlers. A session takes one
564	   564		 * prompt at a time: a Java agent answers a second prompt sent before the first is answered with
565	   565		 * {@code -32600}.
566	   566		 *
567	   567		 * <p>The answer is delivered only once the session update handlers have finished with every
568	   568		 * notification the agent sent before it, so what they collected for the turn is complete when
569	   569		 * the stop reason arrives. A slow update handler delays the answer, and the wait counts against the
570	   570		 * prompt timeout, if one is set. The one exception: an update handler that was already running when
571	   571		 * the prompt was sent, and is still running when its answer arrives, is not waited for, since
572	   572		 * it may be the one waiting for the prompt. An update handler must therefore not wait for this prompt
573	   573		 * to complete.
574	   574		 *
575	   575		 * <p>A prompt is not bound by the builder's {@code requestTimeout}: by default it waits for the
576	   576		 * end of the turn however long that takes. Set {@link AcpClient.AsyncSpec#promptTimeout} to
577	   577		 * bound it; when that passes, the call fails with a
578	   578		 * {@link java.util.concurrent.TimeoutException} and the client sends {@code $/cancel_request},
579	   579		 * which makes a Java agent cancel the turn. Disposing the returned {@code Mono} does the same
580	   580		 * at any time.
581	   581		 * @param request the session ID and the prompt's content blocks
582	   582		 * @return a {@code Mono} emitting the agent's answer, with the stop reason
583	   583		 * @see AcpSchema#METHOD_SESSION_PROMPT
584	   584		 */
585	   585		public Mono<AcpSchema.PromptResponse> prompt(AcpSchema.PromptRequest request) {
586	   586			Assert.notNull(request, "Prompt request must not be null");
587	   587			logger.debug("Sending prompt to session: {}", request.sessionId());
588	   588			return afterInitialize(AcpSchema.METHOD_SESSION_PROMPT,
589	   589					withPromptContent(AcpAsyncClient::initializedOnly, request.prompt()), () -> {
590	   590				if (session instanceof AcpClientSession clientSession) {
591	   591					return clientSession.sendRequest(AcpSchema.METHOD_SESSION_PROMPT, request,
592	   592							PROMPT_RESPONSE_TYPE_REF, this.promptTimeout);
593	   593				}
594	   594				return session.sendRequest(AcpSchema.METHOD_SESSION_PROMPT, request, PROMPT_RESPONSE_TYPE_REF);
595	   595			});
596	   596		}
597	   597	
598	   598		/**
599	   599		 * Sends a prompt as {@link #prompt(AcpSchema.PromptRequest)} does, and stops its turn when
600	   600		 * {@code stop} is cancelled: the client then sends {@code session/cancel} for the prompt's
601	   601		 * session ({@link #cancel}), once, and keeps waiting for the agent's answer, which ACP requires
602	   602		 * to be stop reason {@code cancelled}. A Java agent answers it itself once its cancel grace
603	   603		 * period has passed. Cancelling {@code stop} after the answer has arrived sends nothing.
604	   604		 * Disposing the returned {@code Mono} still gives up on the prompt with
605	   605		 * {@code $/cancel_request}, as for the one-argument method.
606	   606		 *
607	   607		 * <pre>{@code
608	   608		 * CancellationSignal stop = new CancellationSignal();
609	   609		 * client.prompt(request, stop).subscribe(response -> show(response.stopReason()));
610	   610		 * // when the user presses Stop:
611	   611		 * stop.cancel();
612	   612		 * }</pre>
613	   613		 * @param request the session ID and the prompt's content blocks
614	   614		 * @param stop the signal that stops the turn
615	   615		 * @return a {@code Mono} emitting the agent's answer, with the stop reason
616	   616		 * @see CancellationSignal
617	   617		 */
618	   618		public Mono<AcpSchema.PromptResponse> prompt(AcpSchema.PromptRequest request, CancellationSignal stop) {
619	   619			Assert.notNull(request, "Prompt request must not be null");
620	   620			Assert.notNull(stop, "Cancellation signal must not be null");
621	   621			return Mono.create(sink -> {
622	   622				// The prompt is subscribed first, so its request is handed to the transport before
623	   623				// a session/cancel the signal triggers.
624	   624				Disposable prompt = prompt(request).contextWrite(sink.contextView())
625	   625					.subscribe(sink::success, sink::error, () -> sink.success());
626	   626				Disposable cancel = stop.whenCancelled()
627	   627					.then(Mono.defer(() -> cancel(new AcpSchema.CancelNotification(request.sessionId()))))
628	   628					.subscribe(v -> {
629	   629					}, error -> logger.debug("No session/cancel sent for session {}: {}", request.sessionId(),
630	   630							error.getMessage()));
631	   631				sink.onDispose(() -> {
632	   632					cancel.dispose();
633	   633					prompt.dispose();
634	   634				});
635	   635			});
636	   636		}
637	   637	
638	   638		/**
639	   639		 * Asks the agent to stop a session's prompt turn ({@code session/cancel}). It is a
640	   640		 * notification: the agent does not answer it.
641	   641		 *
642	   642		 * <p>The cancel does not end the turn. The agent may still send {@code session/update}s, which
643	   643		 * reach the session update handlers as usual, and then answers the pending prompt with stop
644	   644		 * reason {@code cancelled}. Send the next prompt on the session once that answer has arrived:
645	   645		 * until then the agent refuses it (ACP v1, prompt turn, Cancellation).
646	   646		 * @param notification the session ID
647	   647		 * @return a {@code Mono} that completes when the notification has been handed to the transport
648	   648		 * @see AcpSchema#METHOD_SESSION_CANCEL
649	   649		 */
650	   650		public Mono<Void> cancel(AcpSchema.CancelNotification notification) {
651	   651			Assert.notNull(notification, "Cancel notification must not be null");
652	   652			logger.debug("Canceling operations for session: {}", notification.sessionId());
653	   653			return afterInitialize(AcpSchema.METHOD_SESSION_CANCEL, AcpAsyncClient::initializedOnly, () -> {
654	   654				// ACP v1, prompt turn, Cancellation: "The Client MUST respond to all pending
655	   655				// session/request_permission requests with the cancelled outcome."
656	   656				if (session instanceof AcpClientSession clientSession) {
657	   657					int answered = clientSession.cancelPermissionRequests(notification.sessionId());
658	   658					if (answered > 0) {
659	   659						logger.debug("Answered {} pending permission request(s) of session {} with cancelled", answered,
660	   660								notification.sessionId());
661	   661					}
662	   662				}
663	   663				return session.sendNotification(AcpSchema.METHOD_SESSION_CANCEL, notification);
664	   664			});
665	   665		}
