727	   727		// --------------------------
728	   728	
729	   729		/**
730	   730		 * A session call's requirement, plus {@code sessionCapabilities.additionalDirectories} when
731	   731		 * the request names additional directories: ACP lets a client send them only to an agent that
732	   732		 * advertises it. No list or an empty one needs nothing more.
733	   733		 */
734	   734		private static Consumer<NegotiatedCapabilities> withDirectories(Consumer<NegotiatedCapabilities> requirement,
735	   735				@Nullable List<String> additionalDirectories) {
736	   736			if (additionalDirectories == null || additionalDirectories.isEmpty()) {
737	   737				return requirement;
738	   738			}
739	   739			return requirement.andThen(NegotiatedCapabilities::requireAdditionalDirectories);
740	   740		}
741	   741	
742	   742		/**
743	   743		 * Adds the MCP transport capabilities the servers of a session call need: HTTP and SSE servers
744	   744		 * only to an agent that advertised them (ACP v1, session setup, "Checking Transport Support");
745	   745		 * stdio servers always.
746	   746		 */
747	   747		private static Consumer<NegotiatedCapabilities> withMcpServers(Consumer<NegotiatedCapabilities> requirement,
748	   748				@Nullable List<AcpSchema.McpServer> mcpServers) {
749	   749			if (mcpServers == null || mcpServers.isEmpty()) {
750	   750				return requirement;
751	   751			}
752	   752			Consumer<NegotiatedCapabilities> required = requirement;
753	   753			for (AcpSchema.McpServer server : mcpServers) {
754	   754				if (server instanceof AcpSchema.McpServerHttp) {
755	   755					required = required.andThen(NegotiatedCapabilities::requireMcpHttp);
756	   756				}
757	   757				else if (server instanceof AcpSchema.McpServerSse) {
758	   758					required = required.andThen(NegotiatedCapabilities::requireMcpSse);
759	   759				}
760	   760			}
761	   761			return required;
762	   762		}
