764	   764		/**
765	   765		 * Adds the prompt capabilities a prompt's content needs: image, audio and embedded resource
766	   766		 * blocks only to an agent that advertised them (ACP v1, prompt turn, "Clients MUST restrict
767	   767		 * types of content according to the Prompt Capabilities"); text and resource links always.
768	   768		 */
769	   769		private static Consumer<NegotiatedCapabilities> withPromptContent(Consumer<NegotiatedCapabilities> requirement,
770	   770				@Nullable List<AcpSchema.ContentBlock> blocks) {
771	   771			if (blocks == null || blocks.isEmpty()) {
772	   772				return requirement;
773	   773			}
774	   774			Consumer<NegotiatedCapabilities> required = requirement;
775	   775			for (AcpSchema.ContentBlock block : blocks) {
776	   776				if (block instanceof AcpSchema.ImageContent) {
777	   777					required = required.andThen(NegotiatedCapabilities::requireImageContent);
778	   778				}
779	   779				else if (block instanceof AcpSchema.AudioContent) {
780	   780					required = required.andThen(NegotiatedCapabilities::requireAudioContent);
781	   781				}
782	   782				else if (block instanceof AcpSchema.Resource) {
783	   783					required = required.andThen(NegotiatedCapabilities::requireEmbeddedContext);
784	   784				}
785	   785			}
786	   786			return required;
787	   787		}
