789	   789		/** No capability needed beyond an initialized connection. */
790	   790		private static void initializedOnly(NegotiatedCapabilities capabilities) {
791	   791			// any agent serves the call
792	   792		}
793	   793	
794	   794		/**
795	   795		 * Sends a call once the connection is initialized, checked when the call is subscribed:
796	   796		 * until the agent has answered {@code initialize} every ACP call but initialize fails with
797	   797		 * {@link IllegalStateException} (extension methods are not checked), and a call that needs a capability the agent did not
798	   798		 * advertise fails with {@link com.agentclientprotocol.sdk.error.AcpCapabilityException}.
799	   799		 * Neither sends anything.
800	   800		 */
801	   801		private <T> Mono<T> afterInitialize(String method, Consumer<NegotiatedCapabilities> requirement,
802	   802				Supplier<Mono<T>> send) {
803	   803			return Mono.defer(() -> {
804	   804				NegotiatedCapabilities capabilities = this.agentCapabilities.get();
805	   805				if (capabilities == null) {
806	   806					return Mono.error(new IllegalStateException("Call initialize() first: the agent has not answered "
807	   807							+ "initialize, so the client does not send " + method));
808	   808				}
809	   809				requirement.accept(capabilities);
810	   810				return send.get();
811	   811			});
812	   812		}
