818	   818		/**
819	   819		 * Closes the client without waiting for the agent: requests waiting for an answer fail, the
820	   820		 * agent's requests being handled are cancelled, session updates not yet handled are dropped,
821	   821		 * and the transport is closed. Closing the transport can still block the calling thread: a
822	   822		 * stdio transport stops the agent process and can take about seven seconds (see
823	   823		 * {@link com.agentclientprotocol.sdk.client.transport.StdioAcpClientTransport}).
824	   824		 */
825	   825		public void close() {
826	   826			logger.debug("Closing ACP client");
827	   827			session.close();
828	   828			transport.close();
829	   829		}
830	   830	
831	   831		/**
832	   832		 * Closes the client gracefully. Requests still waiting for an answer, a prompt included, fail
833	   833		 * at once, and the agent's requests being handled are cancelled and answered {@code -32800}.
834	   834		 * Session updates already received are still handed to the update handlers, waiting at most the
835	   835		 * request timeout, and then the transport closes gracefully. For a
836	   836		 * {@link com.agentclientprotocol.sdk.client.transport.StdioAcpClientTransport} that closes the
837	   837		 * agent's input first and gives the agent time to exit.
838	   838		 * @return a {@code Mono} that completes when the transport has closed
839	   839		 */
840	   840		public Mono<Void> closeGracefully() {
841	   841			logger.debug("Gracefully closing ACP client");
842	   842			return session.closeGracefully().then(transport.closeGracefully());
843	   843		}
