 29	/**
 30	 * Default implementation of {@link AcpAsyncAgent} that provides non-blocking
 31	 * operations for handling client requests.
 32	 *
 33	 * <p>
 34	 * This implementation creates an {@link AcpAgentSession} to manage the JSON-RPC
 35	 * communication and installs in it the handlers its builder registered
 36	 * ({@link AgentHandlers}).
 37	 * </p>
 38	 *
 39	 * @author Mark Pollack
 40	 */
 41	class DefaultAcpAsyncAgent implements AcpAsyncAgent {
 42	
 43		private static final Logger logger = LoggerFactory.getLogger(DefaultAcpAsyncAgent.class);
 44	
 45		private final AcpAgentTransport transport;
 46	
 47		private final Duration requestTimeout;
 48	
 49		private final PromptTimeouts promptTimeouts;
 50	
 51		private final List<AgentHandlers.Request<?>> requestHandlers;
 52	
 53		private final List<AgentHandlers.Notification<?>> notificationHandlers;
 54	
 55		/**
 56		 * The session serving this agent; null until {@link #start()}, then never null again.
 57		 * Each method reads it once into a local, so its null check and its call see one value.
 58		 */
 59		private volatile @Nullable AcpAgentSession session;
 60	
 61		/**
 62		 * Capabilities negotiated with the client during initialization.
 63		 */
 64		private final AtomicReference<@Nullable NegotiatedCapabilities> clientCapabilities = new AtomicReference<>();
 65	
 66		/** The cancellation signals of the prompts running, which their contexts read. */
 67		private final PromptCancellations promptCancellations = new PromptCancellations();
 68	
 69		DefaultAcpAsyncAgent(AcpAgentTransport transport, Duration requestTimeout, PromptTimeouts promptTimeouts,
 70				AgentHandlers handlers) {
 71			this.transport = transport;
 72			this.requestTimeout = requestTimeout;
 73			this.promptTimeouts = promptTimeouts;
 74			this.requestHandlers = handlers.requests();
 75			this.notificationHandlers = handlers.notifications();
 76		}
 77	
 78		@Override
 79		public Mono<Void> start() {
 80			return Mono.fromRunnable(() -> {
 81				logger.info("Starting ACP async agent");
 82				Map<String, AcpAgentSession.RequestHandler<?>> requests = new HashMap<>();
 83				for (AgentHandlers.Request<?> registration : requestHandlers) {
 84					requests.put(registration.method(), sessionHandler(registration));
 85				}
 86				Map<String, AcpAgentSession.NotificationHandler> notifications = new HashMap<>();
 87				for (AgentHandlers.Notification<?> registration : notificationHandlers) {
 88					notifications.put(registration.method(), sessionHandler(registration));
 89				}
 90				notifications.put(AcpSchema.METHOD_SESSION_CANCEL,
 91						signalCancel(notifications.get(AcpSchema.METHOD_SESSION_CANCEL)));
 92				this.session = new AcpAgentSession(requestTimeout, transport, requests, notifications, promptTimeouts);
 93				logger.info("ACP async agent started");
 94			});
 95		}
 96	
 97		/** Reads the params as the registered request type, then calls the registered handler. */
 98		private <T> AcpAgentSession.RequestHandler<Object> sessionHandler(AgentHandlers.Request<T> registration) {
 99			return params -> {
100				T request = transport.unmarshalParams(params, registration.requestType());
101				recordClientCapabilities(request);
102				if (request instanceof AcpSchema.PromptRequest prompt) {
103					return handlePrompt(registration, request, prompt.sessionId());
104				}
105				return registration.handler()
106					.handle(request, this)
107					.cast(Object.class)
108					.map(this::withoutBooleanOptionsUnlessAdvertised);
109			};
110		}
111	
112		/**
113		 * ACP v1, session config options: "Agents MUST NOT include type: "boolean" options in
114		 * configOptions payloads unless the Client advertised support." A boolean option the handler
115		 * returned to any other client is omitted, with a warning naming it; the agent keeps using its
116		 * default, which the protocol requires it to have.
117		 */
118		private Object withoutBooleanOptionsUnlessAdvertised(Object result) {
119			NegotiatedCapabilities caps = clientCapabilities.get();
120			if (caps != null && caps.supportsBooleanConfigOptions()) {
121				return result;
122			}
123			Object gated = withoutBooleansInSessionAnswer(result);
124			return (gated != null) ? gated : withoutBooleansInConfigAnswer(result);
125		}
126	
127		/** The session lifecycle answers that carry config options, or null when {@code result} is none. */
128		private static @Nullable Object withoutBooleansInSessionAnswer(Object result) {
129			if (result instanceof AcpSchema.NewSessionResponse r) {
130				return hasBoolean(r.configOptions()) ? new AcpSchema.NewSessionResponse(r.sessionId(), r.modes(),
131						withoutBooleans(r.configOptions()), r.meta()) : r;
132			}
133			if (result instanceof AcpSchema.LoadSessionResponse r) {
134				return hasBoolean(r.configOptions())
135						? new AcpSchema.LoadSessionResponse(r.modes(), withoutBooleans(r.configOptions()), r.meta()) : r;
136			}
137			if (result instanceof AcpSchema.ResumeSessionResponse r) {
138				return hasBoolean(r.configOptions())
139						? new AcpSchema.ResumeSessionResponse(r.modes(), withoutBooleans(r.configOptions()), r.meta()) : r;
140			}
141			if (result instanceof AcpSchema.ForkSessionResponse r) {
142				return hasBoolean(r.configOptions()) ? new AcpSchema.ForkSessionResponse(r.sessionId(), r.modes(),
143						withoutBooleans(r.configOptions()), r.meta()) : r;
144			}
145			return null;
146		}
147	
148		/** The config option answer and update, or {@code result} unchanged when it is neither. */
149		private static Object withoutBooleansInConfigAnswer(Object result) {
150			if (result instanceof AcpSchema.SetSessionConfigOptionResponse r && hasBoolean(r.configOptions())) {
151				return new AcpSchema.SetSessionConfigOptionResponse(withoutBooleans(r.configOptions()), r.meta());
152			}
153			if (result instanceof AcpSchema.ConfigOptionUpdate u && hasBoolean(u.configOptions())) {
154				return new AcpSchema.ConfigOptionUpdate(u.sessionUpdate(), withoutBooleans(u.configOptions()), u.meta());
155			}
156			return result;
157		}
158	
159		private static boolean hasBoolean(@Nullable List<AcpSchema.SessionConfigOption> options) {
160			return options != null && options.stream().anyMatch(AcpSchema.SessionConfigBoolean.class::isInstance);
161		}
162	
163		private static List<AcpSchema.SessionConfigOption> withoutBooleans(
164				@Nullable List<AcpSchema.SessionConfigOption> options) {
165			if (options == null) {
166				return List.of();
167			}
168			List<AcpSchema.SessionConfigOption> kept = new java.util.ArrayList<>(options.size());
169			for (AcpSchema.SessionConfigOption option : options) {
170				if (option instanceof AcpSchema.SessionConfigBoolean bool) {
171					logger.warn("Omitting boolean session config option '{}': the client did not advertise "
172							+ "session.configOptions.boolean (ACP v1, session config options)", bool.id());
173				}
174				else {
175					kept.add(option);
176				}
177			}
178			return List.copyOf(kept);
179		}
