181		/**
182		 * Calls a prompt handler with its cancellation signal started, so its context sees it,
183		 * and signals it when the handler's subscription is cancelled: by {@code $/cancel_request},
184		 * a prompt deadline, or the session closing. {@code session/cancel} signals it through
185		 * {@link #signalCancel}.
186		 */
187		private <T> Mono<Object> handlePrompt(AgentHandlers.Request<T> registration, T request, String sessionId) {
188			PromptCancellations.Signal signal = promptCancellations.start(sessionId);
189			Mono<?> handled;
190			try {
191				handled = registration.handler().handle(request, this);
192			}
193			catch (RuntimeException | Error ex) {
194				promptCancellations.end(sessionId, signal);
195				throw ex;
196			}
197			return handled.cast(Object.class)
198				.doOnCancel(signal::cancel)
199				.doFinally(ignored -> promptCancellations.end(sessionId, signal));
200		}
201	
202		/**
203		 * Handles {@code session/cancel}: signals the session's running prompt, then calls the
204		 * registered cancel handler, if any.
205		 */
206		private AcpAgentSession.NotificationHandler signalCancel(AcpAgentSession.@Nullable NotificationHandler registered) {
207			return params -> {
208				AcpSchema.CancelNotification cancel = transport.unmarshalParams(params,
209						new TypeRef<AcpSchema.CancelNotification>() {
210						});
211				promptCancellations.cancel(cancel.sessionId());
212				return (registered != null) ? registered.handle(params) : Mono.empty();
213			};
214		}
