216		/**
217		 * The cancellation signal of the prompt running on {@code sessionId}; one that never
218		 * fires when there is none (a context built outside a running prompt).
219		 */
220		PromptCancellations.Signal promptSignal(String sessionId) {
221			PromptCancellations.Signal signal = promptCancellations.current(sessionId);
222			return (signal != null) ? signal : new PromptCancellations.Signal();
223		}
