225		/**
226		 * Whether the prompt running on {@code sessionId} has been answered; always false when no
227		 * prompt is running (a context built outside a running prompt).
228		 */
229		BooleanSupplier promptAnswered(String sessionId) {
230			AcpAgentSession current = this.session;
231			return (current != null) ? current.promptAnswered(sessionId) : () -> false;
232		}
