368		/**
369		 * Sends a request to the client, unless the agent is not started or the client said
370		 * during initialization that it does not support the capability the request needs.
371		 * Before initialization nothing is known, and the request is sent.
372		 */
373		private <T> Mono<T> sendRequest(String method, Object request, TypeRef<T> responseType,
374				Predicate<NegotiatedCapabilities> clientSupports, String capability) {
375			AcpAgentSession current = this.session;
376			if (current == null) {
377				return Mono.error(new IllegalStateException("Agent not started"));
378			}
379			NegotiatedCapabilities caps = clientCapabilities.get();
380			if (caps != null && !clientSupports.test(caps)) {
381				return Mono.error(new AcpCapabilityException(capability));
382			}
383			return current.sendRequest(method, request, responseType);
384		}
