225 if (map == null) {
226 // The JSON null literal: valid JSON, but no JSON-RPC message
227 throw new IllegalArgumentException("Cannot deserialize JSONRPCMessage: the JSON null literal");
228 }
229 Class<? extends JSONRPCMessage> messageType = messageType(map);
230 if (messageType == null) {
231 // Not the text, here or in validateRequest: a transport logs these exceptions, and
232 // the text is the peer's payload.
233 throw new IllegalArgumentException(
