201		public Mono<String> askChoice(String question, String... options) {
202			if (options == null || options.length < 2) {
203				return Mono.error(new IllegalArgumentException("At least 2 options are required"));
204			}
206			List<PermissionOption> permOptions = new ArrayList<>();
207			for (int i = 0; i < options.length; i++) {
208				permOptions.add(new PermissionOption(
209						String.valueOf(i), options[i], PermissionOptionKind.ALLOW_ONCE));
210			}
212			return ask(question, ToolKind.OTHER, permOptions)
213					.flatMap(response -> {
214						if (response.outcome() instanceof PermissionSelected s) {
215							for (int i = 0; i < options.length; i++) {
216								if (String.valueOf(i).equals(s.optionId())) {
217									return Mono.just(options[i]);
218								}
219							}
220							return Mono.error(AcpError.rejectedResponse(AcpSchema.METHOD_SESSION_REQUEST_PERMISSION,
221									"unoffered-option", "The client chose option '" + s.optionId()
222											+ "', which askChoice did not offer (0 to " + (options.length - 1) + ")",
223									Map.of("optionId", s.optionId())));
224						}
225						return Mono.empty();
226					});
227		}
