234		@Override
235		public Mono<CommandResult> execute(Command command) {
236			// Convert env map to list of EnvVariable; no variables leaves the wire field out
237			List<EnvVariable> envList = null;
238			if (!command.env().isEmpty()) {
239				envList = command.env().entrySet().stream()
240						.map(e -> new EnvVariable(e.getKey(), e.getValue()))
241						.toList();
242			}
244			return client.createTerminal(new CreateTerminalRequest(
245					sessionId, command.executable(), command.args(),
246					command.cwd(), envList, command.outputByteLimit()))
247				.flatMap(createResp -> {
248					String terminalId = createResp.terminalId();
249					ReleaseTerminalRequest releaseReq = new ReleaseTerminalRequest(sessionId, terminalId);
250					// ACP: the agent MUST release every terminal it created (terminals.mdx), so the
251					// terminal is released exactly once whether the command ends, a step fails, or the
252					// caller cancels (the prompt was cancelled or timed out).
253					AtomicBoolean releaseSent = new AtomicBoolean();
254					Mono<Void> release = Mono.defer(() -> releaseSent.compareAndSet(false, true)
255							? client.releaseTerminal(releaseReq).then() : Mono.empty());
257					return client.waitForTerminalExit(new WaitForTerminalExitRequest(sessionId, terminalId))
258							.flatMap(exitResp -> client.getTerminalOutput(new TerminalOutputRequest(sessionId, terminalId))
259									.map(outputResp -> new CommandResult(outputResp.output(), exitResp.exitCode(),
260											exitResp.signal(), outputResp.truncated())))
261							// Release terminal after getting result, then return result
262							.flatMap(result -> release.thenReturn(result))
263							// On error, still release terminal before propagating error
264							.onErrorResume(error -> release.then(Mono.error(error)))
265							// Cancelled: nobody waits for the release any more, so send it on its own
266							.doOnCancel(() -> release.subscribe(v -> {
267							}, error -> logReleaseFailure(terminalId, error)));
268				});
269		}
275		private static void logReleaseFailure(String terminalId, Throwable error) {
276			if (error instanceof AcpError clientError) {
277				logger.warn("Could not release terminal {} of a cancelled command: the client answered {} {}", terminalId,
278						clientError.getCode(), AcpErrorCodes.getDescription(clientError.getCode()));
279				logger.debug("Could not release terminal {}: {}", terminalId, clientError.toString());
280			}
281			else {
282				logger.warn("Could not release terminal {} of a cancelled command: {}", terminalId, error.getMessage());
283			}
284		}
