 55		Mono<AcpSchema.JSONRPCResponse> answer(ActivePrompts.Turn turn, AcpSchema.JSONRPCRequest request,
 56				Mono<AcpSchema.JSONRPCResponse> handled) {
 57			if (!this.timeouts.hasCancelGracePeriod() && !this.timeouts.hasMaxPromptDuration()) {
 58				return handled;
 59			}
 60			return Mono.create(sink -> {
 61				PromptAnswer answer = turn.answer();
 62				// Disposed once the response is out or the prompt is cancelled downstream: the
 63				// timers, and the handler's subscription when a deadline answered.
 64				Disposable.Composite resources = Disposables.composite();
 65				sink.onDispose(resources);
 66				if (this.timeouts.hasCancelGracePeriod()) {
 67					startGracePeriodOnCancel(turn, request, sink, resources);
 68				}
 69				if (this.timeouts.hasMaxPromptDuration()) {
 70					resources.add(after(this.timeouts.maxPromptDuration(), () -> maxDurationExpired(answer, request, sink)));
 71				}
 72				resources.add(handled.contextWrite(sink.contextView())
 73					.subscribe(response -> handlerAnswered(answer, () -> sink.success(response)),
 74							error -> handlerAnswered(answer, () -> sink.error(error))));
 75			});
 76		}
 78		private static void handlerAnswered(PromptAnswer answer, Runnable publish) {
 79			if (answer.handlerAnswered()) {
 80				publish.run();
 81			}
 82		}
 85		private void startGracePeriodOnCancel(ActivePrompts.Turn turn, AcpSchema.JSONRPCRequest request,
 86				MonoSink<AcpSchema.JSONRPCResponse> sink, Disposable.Composite resources) {
 87			AtomicBoolean started = new AtomicBoolean();
 88			turn.onCancelRequested(() -> {
 89				if (started.compareAndSet(false, true)) {
 90					resources.add(after(this.timeouts.cancelGracePeriod(), () -> graceExpired(turn.answer(), request, sink)));
 91				}
 92			});
 93		}
