 98				logger.warn("Prompt {} not answered {} after session/cancel; answering cancelled", request.id(),
 99						this.timeouts.cancelGracePeriod());
100				sink.success(cancelled(request));
101			}
102		}
104		private void maxDurationExpired(PromptAnswer answer, AcpSchema.JSONRPCRequest request,
105				MonoSink<AcpSchema.JSONRPCResponse> sink) {
106			PromptAnswer.Forced forced = answer.maxDurationExpired();
107			if (forced == null) {
108				return;
109			}
110			logger.warn("Prompt {} ran past maxPromptDuration {}; answering {}", request.id(),
111					this.timeouts.maxPromptDuration(), forced);
112			sink.success(forced == PromptAnswer.Forced.CANCELLED ? cancelled(request) : expired(request));
113		}
115		private Disposable after(Duration delay, Runnable action) {
116			return this.timer.apply(delay).subscribe(tick -> action.run());
117		}
119		private static AcpSchema.JSONRPCResponse cancelled(AcpSchema.JSONRPCRequest request) {
120			return InboundMessages.result(request, new AcpSchema.PromptResponse(AcpSchema.StopReason.CANCELLED));
121		}
